async function* splitLines(source) {
  let buf = '';
  for await (const chunk of source) {
    buf += chunk;
    let i;
    while ((i = buf.indexOf('\n')) >= 0) {
      yield buf.slice(0, i);
      buf = buf.slice(i + 1);
    }
  }
  if (buf) yield buf;   // flush the trailing record
}
